-- =============================================================================
-- Guardian (parent) access.
--
-- Linking: a guardian record created by a school is linked to an app account
--   1. automatically, when the account's VERIFIED email matches the guardian
--      email the school entered (both directions: account created first or
--      guardian record created first), or
--   2. explicitly, when the parent redeems a one-time invite code generated by
--      the school. Codes are stored hashed, expire, and redemption is rate
--      limited.
--
-- Reading: guardians never query tables directly. The guardian_* functions
-- below return the curated, parent-safe view of a child's data, honouring the
-- school's enabled modules and publication flags.
-- =============================================================================

create extension if not exists pgcrypto with schema extensions;

-- -----------------------------------------------------------------------------
-- Account <-> guardian linking by verified email
-- -----------------------------------------------------------------------------

create function private.find_verified_user_by_email(p_email text)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select u.id
  from auth.users u
  where lower(u.email) = lower(p_email)
    and u.email_confirmed_at is not null
    and u.deleted_at is null
    and coalesce(u.is_anonymous, false) = false
  order by u.created_at
  limit 1;
$$;

-- Fills in the link when a school creates a guardian, or re-links when the
-- guardian email changes. Runs after guard_guardian_link (trigger names are
-- ordered alphabetically), so the client-supplied row has already been checked.
create function private.link_guardian_by_email()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid;
begin
  if tg_op = 'UPDATE'
     and new.email is distinct from old.email
     and old.link_method = 'email'
     and new.user_id is not distinct from old.user_id then
    new.user_id := null;
    new.link_method := null;
    new.linked_at := null;
  end if;

  if new.user_id is null and new.email is not null then
    v_user_id := private.find_verified_user_by_email(new.email);
    if v_user_id is not null then
      new.user_id := v_user_id;
      new.link_method := 'email';
      new.linked_at := now();
    end if;
  end if;
  return new;
end;
$$;

create trigger link_guardian_by_email before insert or update of email on public.guardians
  for each row execute function private.link_guardian_by_email();

-- Links every unlinked guardian record whose email matches the user's verified email.
create function private.link_guardians_for_user(p_user_id uuid)
returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_email text;
  v_count integer;
begin
  select u.email into v_email
  from auth.users u
  where u.id = p_user_id
    and u.email_confirmed_at is not null
    and u.deleted_at is null
    and coalesce(u.is_anonymous, false) = false;

  if v_email is null then
    return 0;
  end if;

  update public.guardians g
  set user_id = p_user_id, link_method = 'email', linked_at = now()
  where g.user_id is null
    and g.email is not null
    and lower(g.email) = lower(v_email);
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- Keeps profiles and guardian links in sync with auth.users.
create function private.handle_auth_user_change()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    insert into public.profiles (id, email, full_name, avatar_url)
    values (
      new.id,
      new.email,
      left(coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'), 200),
      left(coalesce(new.raw_user_meta_data ->> 'avatar_url', new.raw_user_meta_data ->> 'picture'), 2048)
    )
    on conflict (id) do nothing;
  else
    update public.profiles set email = new.email
    where id = new.id and email is distinct from new.email;

    -- Email changed: drop links that were based on the old address.
    if new.email is distinct from old.email then
      update public.guardians g
      set user_id = null, link_method = null, linked_at = null
      where g.user_id = new.id
        and g.link_method = 'email'
        and (new.email is null or lower(g.email) <> lower(new.email));
    end if;
  end if;

  perform private.link_guardians_for_user(new.id);
  return null;
end;
$$;

create trigger on_auth_user_change
  after insert or update of email, email_confirmed_at on auth.users
  for each row execute function private.handle_auth_user_change();

-- Lets the apps re-run linking after sign-in (idempotent, cheap).
create function public.link_my_guardian_records()
returns integer
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select auth.uid()) is null then
    raise exception using errcode = '42501', message = 'not_authenticated';
  end if;
  return private.link_guardians_for_user((select auth.uid()));
end;
$$;

-- -----------------------------------------------------------------------------
-- Invite codes
-- -----------------------------------------------------------------------------

create table public.guardian_invites (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null,
  guardian_id uuid not null,
  code_hash bytea not null unique,
  expires_at timestamptz not null,
  created_by uuid default auth.uid() references auth.users (id) on delete set null,
  redeemed_at timestamptz,
  redeemed_by uuid references auth.users (id) on delete set null,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (school_id, guardian_id) references public.guardians (school_id, id) on delete cascade
);

create index guardian_invites_guardian_idx on public.guardian_invites (guardian_id, created_at desc);
create index guardian_invites_school_idx on public.guardian_invites (school_id, created_at desc);

select private.attach_standard_triggers('public.guardian_invites');

alter table public.guardian_invites enable row level security;

create policy guardian_invites_select on public.guardian_invites for select to authenticated
  using ((select private.is_platform_admin()) or school_id in (select private.staff_school_ids()));
create policy guardian_invites_update on public.guardian_invites for update to authenticated
  using ((select private.is_platform_admin()) or school_id in (select private.staff_school_ids()))
  with check ((select private.is_platform_admin()) or school_id in (select private.staff_school_ids()));

-- The hash is never readable; staff may only revoke.
grant select (id, school_id, guardian_id, expires_at, created_by, redeemed_at, redeemed_by, revoked_at, created_at, updated_at)
  on public.guardian_invites to authenticated;
grant update (revoked_at) on public.guardian_invites to authenticated;
grant all on public.guardian_invites to service_role;

create table public.guardian_invite_attempts (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  succeeded boolean not null,
  attempted_at timestamptz not null default now()
);

create index guardian_invite_attempts_user_idx on public.guardian_invite_attempts (user_id, attempted_at desc);

alter table public.guardian_invite_attempts enable row level security;
grant all on public.guardian_invite_attempts to service_role;

create function private.normalize_invite_code(p_code text)
returns text
language sql
immutable
set search_path = ''
as $$
  -- Crockford decoding rules: case-insensitive, O reads as 0, I and L read as 1.
  select translate(upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g')), 'OIL', '011');
$$;

create function private.hash_invite_code(p_code text)
returns bytea
language sql
immutable
set search_path = ''
as $$
  select sha256(convert_to(private.normalize_invite_code(p_code), 'UTF8'));
$$;

-- Creates a new invite for a guardian, revoking any earlier active invite.
-- The plain code is returned exactly once; only its hash is stored.
create function public.create_guardian_invite(p_guardian_id uuid, p_valid_days integer default 14)
returns table (invite_id uuid, code text, expires_at timestamptz)
language plpgsql
security definer
set search_path = ''
as $$
declare
  -- Crockford base32 (no I, L, O, U): 10 characters = 50 bits of entropy.
  c_alphabet constant text := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  v_school_id uuid;
  v_bytes bytea;
  v_code text := '';
  v_invite_id uuid;
  v_expires_at timestamptz;
  i integer;
begin
  select g.school_id into v_school_id from public.guardians g where g.id = p_guardian_id;
  if v_school_id is null or not private.can_manage_school(v_school_id) then
    raise exception using errcode = '42501', message = 'guardian_not_accessible';
  end if;
  if p_valid_days is null or p_valid_days not between 1 and 90 then
    raise exception using errcode = 'SC020', message = 'invalid_invite_validity';
  end if;

  update public.guardian_invites gi
  set revoked_at = now()
  where gi.guardian_id = p_guardian_id
    and gi.redeemed_at is null
    and gi.revoked_at is null
    and gi.expires_at > now();

  v_bytes := extensions.gen_random_bytes(10);
  for i in 0..9 loop
    v_code := v_code || substr(c_alphabet, (get_byte(v_bytes, i) % 32) + 1, 1);
  end loop;
  v_expires_at := now() + make_interval(days => p_valid_days);

  insert into public.guardian_invites (school_id, guardian_id, code_hash, expires_at)
  values (v_school_id, p_guardian_id, private.hash_invite_code(v_code), v_expires_at)
  returning id into v_invite_id;

  return query select v_invite_id, substr(v_code, 1, 5) || '-' || substr(v_code, 6, 5), v_expires_at;
end;
$$;

-- Redeems an invite code for the current user. Returns a status instead of
-- raising so that failed attempts are recorded for rate limiting.
--   status: 'linked' | 'invalid' | 'already_linked' | 'rate_limited'
create function public.redeem_guardian_invite(p_code text)
returns table (status text, school_id uuid, school_name text)
language plpgsql
security definer
set search_path = ''
as $$
declare
  c_max_failures constant integer := 10;
  v_user_id uuid := (select auth.uid());
  v_invite public.guardian_invites%rowtype;
  v_guardian_user uuid;
  v_school_name text;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'not_authenticated';
  end if;

  if (
    select count(*) from public.guardian_invite_attempts a
    where a.user_id = v_user_id and not a.succeeded and a.attempted_at > now() - interval '1 hour'
  ) >= c_max_failures then
    return query select 'rate_limited'::text, null::uuid, null::text;
    return;
  end if;

  select gi.* into v_invite
  from public.guardian_invites gi
  join public.schools s on s.id = gi.school_id and s.status = 'active'
  where gi.code_hash = private.hash_invite_code(p_code)
    and gi.redeemed_at is null
    and gi.revoked_at is null
    and gi.expires_at > now()
  for update of gi;

  if not found then
    insert into public.guardian_invite_attempts (user_id, succeeded) values (v_user_id, false);
    return query select 'invalid'::text, null::uuid, null::text;
    return;
  end if;

  select g.user_id into v_guardian_user from public.guardians g where g.id = v_invite.guardian_id for update;
  select s.name into v_school_name from public.schools s where s.id = v_invite.school_id;

  if v_guardian_user is not null and v_guardian_user <> v_user_id then
    insert into public.guardian_invite_attempts (user_id, succeeded) values (v_user_id, false);
    return query select 'already_linked'::text, v_invite.school_id, v_school_name;
    return;
  end if;

  update public.guardians g
  set user_id = v_user_id, link_method = 'invite', linked_at = now()
  where g.id = v_invite.guardian_id and g.user_id is null;

  update public.guardian_invites gi
  set redeemed_at = now(), redeemed_by = v_user_id
  where gi.id = v_invite.id;

  insert into public.guardian_invite_attempts (user_id, succeeded) values (v_user_id, true);
  return query select 'linked'::text, v_invite.school_id, v_school_name;
end;
$$;

-- -----------------------------------------------------------------------------
-- Guardian access helpers
-- -----------------------------------------------------------------------------

-- Students (in active schools) linked to the current user as a guardian.
create function private.guardian_student_ids()
returns setof uuid
language sql
stable
security definer
set search_path = ''
as $$
  select sg.student_id
  from public.guardians g
  join public.student_guardians sg on sg.guardian_id = g.id
  join public.schools s on s.id = g.school_id
  where g.user_id = (select auth.uid())
    and s.status = 'active';
$$;

-- Resolves the school context of a student the current user may view as a
-- guardian (or as staff/platform admin, for "preview as parent"). Raises when
-- the student is not accessible.
create function private.student_access_context(
  p_student_id uuid,
  out school_id uuid,
  out enabled_modules public.school_module[]
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  select s.school_id, sc.enabled_modules
  into school_id, enabled_modules
  from public.students s
  join public.schools sc on sc.id = s.school_id
  where s.id = p_student_id
    and (
      (select private.is_platform_admin())
      or (
        sc.status = 'active'
        and (
          s.id in (select private.guardian_student_ids())
          or s.school_id in (select private.staff_school_ids())
        )
      )
    );

  if school_id is null then
    raise exception using errcode = '42501', message = 'student_not_accessible';
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Guardian read API
-- -----------------------------------------------------------------------------

create function public.guardian_children()
returns table (
  student_id uuid,
  school_id uuid,
  school_name text,
  school_logo_path text,
  school_primary_color text,
  school_timezone text,
  enabled_modules public.school_module[],
  first_name text,
  last_name text,
  preferred_name text,
  grade_level text,
  section text,
  photo_path text,
  status public.student_status,
  relationship public.guardian_relationship
)
language sql
stable
security definer
set search_path = ''
as $$
  select distinct on (st.id)
    st.id, sc.id, sc.name, sc.logo_path, sc.primary_color::text, sc.timezone, sc.enabled_modules,
    st.first_name, st.last_name, st.preferred_name, st.grade_level, st.section, st.photo_path,
    st.status, sg.relationship
  from public.guardians g
  join public.student_guardians sg on sg.guardian_id = g.id
  join public.students st on st.id = sg.student_id
  join public.schools sc on sc.id = st.school_id
  where g.user_id = (select auth.uid())
    and sc.status = 'active'
  order by st.id, sg.is_primary desc;
$$;

create function public.guardian_student_profile(p_student_id uuid)
returns table (
  student_id uuid,
  school_id uuid,
  student_number text,
  first_name text,
  last_name text,
  preferred_name text,
  date_of_birth date,
  gender public.gender,
  grade_level text,
  section text,
  photo_path text,
  status public.student_status,
  enrolled_on date,
  -- [{ key, label, type, value }] for fields the school marked guardian-visible
  custom_fields jsonb
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_ctx record;
begin
  v_ctx := private.student_access_context(p_student_id);

  return query
  select
    st.id, st.school_id, st.student_number, st.first_name, st.last_name, st.preferred_name,
    st.date_of_birth, st.gender, st.grade_level, st.section, st.photo_path, st.status, st.enrolled_on,
    coalesce((
      select jsonb_agg(
        jsonb_build_object('key', d.key, 'label', d.label, 'type', d.field_type, 'value', st.custom_fields -> d.key)
        order by d.sort_order, d.label
      )
      from public.custom_field_definitions d
      where d.school_id = st.school_id
        and d.entity = 'student'
        and d.visible_to_guardians
        and st.custom_fields ? d.key
    ), '[]'::jsonb)
  from public.students st
  where st.id = p_student_id;
end;
$$;

create function public.guardian_student_courses(p_student_id uuid)
returns table (
  course_id uuid,
  name text,
  code text,
  subject text,
  color text,
  term_id uuid,
  term_name text,
  -- [{ id, title, first_name, last_name, email, subject, photo_path }]
  teachers jsonb
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_ctx record;
begin
  v_ctx := private.student_access_context(p_student_id);
  if not ('courses' = any (v_ctx.enabled_modules)) then
    return;
  end if;

  return query
  select
    c.id, c.name, c.code, c.subject, c.color::text, t.id, t.name,
    case when 'teachers' = any (v_ctx.enabled_modules) then
      coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', te.id, 'title', te.title, 'first_name', te.first_name, 'last_name', te.last_name,
          'email', te.email, 'subject', te.subject, 'photo_path', te.photo_path
        ) order by te.last_name, te.first_name)
        from public.course_teachers ct
        join public.teachers te on te.id = ct.teacher_id
        where ct.course_id = c.id
      ), '[]'::jsonb)
    else '[]'::jsonb end
  from public.enrollments e
  join public.courses c on c.id = e.course_id
  left join public.academic_terms t on t.id = c.term_id
  where e.student_id = p_student_id
  order by t.starts_on desc nulls last, c.name;
end;
$$;

create function public.guardian_student_grades(p_student_id uuid, p_term_id uuid default null)
returns table (
  grade_id uuid,
  assessment_id uuid,
  assessment_title text,
  assessment_kind public.assessment_kind,
  assessed_on date,
  max_score numeric,
  weight numeric,
  score numeric,
  letter text,
  comment text,
  course_id uuid,
  course_name text,
  term_id uuid,
  published_at timestamptz
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_ctx record;
begin
  v_ctx := private.student_access_context(p_student_id);
  if not ('grades' = any (v_ctx.enabled_modules)) then
    return;
  end if;

  return query
  select
    g.id, a.id, a.title, a.kind, a.assessed_on, a.max_score, a.weight,
    g.score, g.letter, g.comment, c.id, c.name, coalesce(a.term_id, c.term_id), a.published_at
  from public.grades g
  join public.assessments a on a.id = g.assessment_id
  join public.courses c on c.id = a.course_id
  where g.student_id = p_student_id
    and a.published_at is not null
    and a.published_at <= now()
    and (p_term_id is null or coalesce(a.term_id, c.term_id) = p_term_id)
  order by a.assessed_on desc nulls last, a.published_at desc;
end;
$$;

create function private.assert_date_range(p_from date, p_to date, p_max_days integer)
returns void
language plpgsql
immutable
set search_path = ''
as $$
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > p_max_days then
    raise exception using errcode = 'SC020', message = 'invalid_date_range';
  end if;
end;
$$;

create function public.guardian_student_attendance(p_student_id uuid, p_from date, p_to date)
returns table (
  record_id uuid,
  attended_on date,
  status public.attendance_status,
  course_id uuid,
  course_name text,
  period text,
  minutes_late integer,
  note text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_ctx record;
begin
  perform private.assert_date_range(p_from, p_to, 366);
  v_ctx := private.student_access_context(p_student_id);
  if not ('attendance' = any (v_ctx.enabled_modules)) then
    return;
  end if;

  return query
  select ar.id, ar.attended_on, ar.status, c.id, c.name, ar.period, ar.minutes_late, ar.note
  from public.attendance_records ar
  left join public.courses c on c.id = ar.course_id
  where ar.student_id = p_student_id
    and ar.attended_on between p_from and p_to
  order by ar.attended_on desc, ar.period nulls first;
end;
$$;

create function public.guardian_student_attendance_summary(p_student_id uuid, p_from date, p_to date)
returns table (status public.attendance_status, total bigint)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_ctx record;
begin
  perform private.assert_date_range(p_from, p_to, 5 * 366);
  v_ctx := private.student_access_context(p_student_id);
  if not ('attendance' = any (v_ctx.enabled_modules)) then
    return;
  end if;

  return query
  select ar.status, count(*)
  from public.attendance_records ar
  where ar.student_id = p_student_id
    and ar.attended_on between p_from and p_to
  group by ar.status
  order by ar.status;
end;
$$;

create function public.guardian_student_notes(
  p_student_id uuid,
  p_before timestamptz default null,
  p_limit integer default 20
)
returns table (
  note_id uuid,
  title text,
  body text,
  category text,
  created_at timestamptz,
  teacher_name text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_ctx record;
begin
  v_ctx := private.student_access_context(p_student_id);
  if not ('notes' = any (v_ctx.enabled_modules)) then
    return;
  end if;

  return query
  select
    n.id, n.title, n.body, n.category, n.created_at,
    nullif(concat_ws(' ', te.title, te.first_name, te.last_name), '')
  from public.student_notes n
  left join public.teachers te on te.id = n.teacher_id
  where n.student_id = p_student_id
    and n.visible_to_guardians
    and (p_before is null or n.created_at < p_before)
  order by n.created_at desc
  limit least(greatest(coalesce(p_limit, 20), 1), 100);
end;
$$;

create function public.guardian_student_events(p_student_id uuid, p_from timestamptz, p_to timestamptz)
returns table (
  event_id uuid,
  title text,
  description text,
  location text,
  starts_at timestamptz,
  ends_at timestamptz,
  all_day boolean,
  color text,
  course_id uuid,
  course_name text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_ctx record;
begin
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > interval '400 days' then
    raise exception using errcode = 'SC020', message = 'invalid_date_range';
  end if;
  v_ctx := private.student_access_context(p_student_id);
  if not ('events' = any (v_ctx.enabled_modules)) then
    return;
  end if;

  return query
  select ev.id, ev.title, ev.description, ev.location, ev.starts_at, ev.ends_at, ev.all_day,
         ev.color::text, c.id, c.name
  from public.events ev
  left join public.courses c on c.id = ev.course_id
  where ev.school_id = v_ctx.school_id
    and ev.visible_to_guardians
    and ev.starts_at < p_to
    and coalesce(ev.ends_at, ev.starts_at) >= p_from
    and (
      ev.course_id is null
      or exists (select 1 from public.enrollments e where e.course_id = ev.course_id and e.student_id = p_student_id)
    )
  order by ev.starts_at;
end;
$$;

-- -----------------------------------------------------------------------------
-- Grants
-- -----------------------------------------------------------------------------

grant execute on function
  private.guardian_student_ids(),
  private.student_access_context(uuid),
  private.assert_date_range(date, date, integer),
  private.normalize_invite_code(text),
  private.hash_invite_code(text)
to authenticated, service_role;

grant execute on function
  public.link_my_guardian_records(),
  public.create_guardian_invite(uuid, integer),
  public.redeem_guardian_invite(text),
  public.guardian_children(),
  public.guardian_student_profile(uuid),
  public.guardian_student_courses(uuid),
  public.guardian_student_grades(uuid, uuid),
  public.guardian_student_attendance(uuid, date, date),
  public.guardian_student_attendance_summary(uuid, date, date),
  public.guardian_student_notes(uuid, timestamptz, integer),
  public.guardian_student_events(uuid, timestamptz, timestamptz)
to authenticated, service_role;
